-- ----------------------------------------------------------------------------
-- TruthValues: The three truth values a membership question or condition can take: True, False, or NULL. Admitting NULL makes membership a partial, non-bivalent semantics rather than the classical two-valued one; bivalence is recovered wherever a definition is grounded.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS truth_values (
  truth_value_id                      TEXT                 PRIMARY KEY          -- Stored identity of the truth value: 'true', 'false', or 'null'.
);
ALTER TABLE truth_values ADD COLUMN IF NOT EXISTS symbol TEXT;                                      -- Single-letter symbol: T, F, or N.
ALTER TABLE truth_values ADD COLUMN IF NOT EXISTS glyph TEXT;                                       -- Logical glyph for the value.
ALTER TABLE truth_values ADD COLUMN IF NOT EXISTS rank INTEGER;                                     -- Strong Kleene order used by min/max: True=1, NULL=0, False=-1.
ALTER TABLE truth_values ADD COLUMN IF NOT EXISTS facts_with_value TEXT;                            -- Membership facts that resolve to this truth value.
COMMENT ON TABLE truth_values IS 'The three truth values a membership question or condition can take: True, False, or NULL. Admitting NULL makes membership a partial, non-bivalent semantics rather than the classical two-valued one; bivalence is recovered wherever a definition is grounded.';
COMMENT ON COLUMN truth_values.truth_value_id IS 'Stored identity of the truth value: ''true'', ''false'', or ''null''.';
COMMENT ON COLUMN truth_values.symbol IS 'Single-letter symbol: T, F, or N.';
COMMENT ON COLUMN truth_values.glyph IS 'Logical glyph for the value.';
COMMENT ON COLUMN truth_values.rank IS 'Strong Kleene order used by min/max: True=1, NULL=0, False=-1.';
COMMENT ON COLUMN truth_values.facts_with_value IS 'Membership facts that resolve to this truth value.';

-- ----------------------------------------------------------------------------
-- Connectives: Logical connectives whose Strong Kleene (K3) truth tables define how NULL propagates. This is the 'gap' route (NULL where evaluation fails to converge), the sibling of paraconsistent 'glut' logics, and it follows Kripke's fixed-point grounding.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS connectives (
  connective_id                       TEXT                 PRIMARY KEY          -- Stored identity: 'negation', 'conjunction', or 'disjunction'.
);
ALTER TABLE connectives ADD COLUMN IF NOT EXISTS symbol TEXT;                                       -- Operator glyph (not / and / or).
ALTER TABLE connectives ADD COLUMN IF NOT EXISTS arity INTEGER;                                     -- Number of inputs: 1 for negation, 2 for conjunction/disjunction.
ALTER TABLE connectives ADD COLUMN IF NOT EXISTS kleene_rule TEXT;                                  -- How the K3 output is computed (negate / min / max over ranks).
ALTER TABLE connectives ADD COLUMN IF NOT EXISTS truth_table_rows TEXT;                             -- The truth-table rows belonging to this connective.
COMMENT ON TABLE connectives IS 'Logical connectives whose Strong Kleene (K3) truth tables define how NULL propagates. This is the ''gap'' route (NULL where evaluation fails to converge), the sibling of paraconsistent ''glut'' logics, and it follows Kripke''s fixed-point grounding.';
COMMENT ON COLUMN connectives.connective_id IS 'Stored identity: ''negation'', ''conjunction'', or ''disjunction''.';
COMMENT ON COLUMN connectives.symbol IS 'Operator glyph (not / and / or).';
COMMENT ON COLUMN connectives.arity IS 'Number of inputs: 1 for negation, 2 for conjunction/disjunction.';
COMMENT ON COLUMN connectives.kleene_rule IS 'How the K3 output is computed (negate / min / max over ranks).';
COMMENT ON COLUMN connectives.truth_table_rows IS 'The truth-table rows belonging to this connective.';

-- ----------------------------------------------------------------------------
-- TruthTableRows: One row per input combination per connective: the Strong Kleene semantics, stored as data.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS truth_table_rows (
  truth_table_row_id                  TEXT                 PRIMARY KEY          -- Stored identity, e.g. 'negation|null|_|null'.
);
ALTER TABLE truth_table_rows ADD COLUMN IF NOT EXISTS connective TEXT;                              -- The connective this row defines.
ALTER TABLE truth_table_rows ADD COLUMN IF NOT EXISTS left_input TEXT;                              -- Left/sole input truth value.
ALTER TABLE truth_table_rows ADD COLUMN IF NOT EXISTS right_input TEXT;                             -- Right input truth value; null for the unary negation.
ALTER TABLE truth_table_rows ADD COLUMN IF NOT EXISTS output TEXT;                                  -- Resulting truth value for this input combination.
COMMENT ON TABLE truth_table_rows IS 'One row per input combination per connective: the Strong Kleene semantics, stored as data.';
COMMENT ON COLUMN truth_table_rows.truth_table_row_id IS 'Stored identity, e.g. ''negation|null|_|null''.';
COMMENT ON COLUMN truth_table_rows.connective IS 'The connective this row defines.';
COMMENT ON COLUMN truth_table_rows.left_input IS 'Left/sole input truth value.';
COMMENT ON COLUMN truth_table_rows.right_input IS 'Right input truth value; null for the unary negation.';
COMMENT ON COLUMN truth_table_rows.output IS 'Resulting truth value for this input combination.';

-- ----------------------------------------------------------------------------
-- SetRules: The twelve structural rules of the theory: the eleven classical naive rules plus the missing Rule 12.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS set_rules (
  set_rule_id                         TEXT                 PRIMARY KEY          -- Stored identity, e.g. 'rule-12'.
);
ALTER TABLE set_rules ADD COLUMN IF NOT EXISTS rule_number INTEGER;                                 -- Ordinal 1-12.
ALTER TABLE set_rules ADD COLUMN IF NOT EXISTS title TEXT;                                          -- Short rule title.
ALTER TABLE set_rules ADD COLUMN IF NOT EXISTS statement TEXT;                                      -- Full statement of the rule.
COMMENT ON TABLE set_rules IS 'The twelve structural rules of the theory: the eleven classical naive rules plus the missing Rule 12.';
COMMENT ON COLUMN set_rules.set_rule_id IS 'Stored identity, e.g. ''rule-12''.';
COMMENT ON COLUMN set_rules.rule_number IS 'Ordinal 1-12.';
COMMENT ON COLUMN set_rules.title IS 'Short rule title.';
COMMENT ON COLUMN set_rules.statement IS 'Full statement of the rule.';

-- ----------------------------------------------------------------------------
-- Sets: The universe of sets under discussion. Each set is identified by a slug and defined by a membership condition.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sets (
  set_id                              TEXT                 PRIMARY KEY          -- Stored identity slug, e.g. 'russell-set'.
);
ALTER TABLE sets ADD COLUMN IF NOT EXISTS label TEXT;                                               -- Human notation for the set, e.g. '{a}', 'R', '∅'.
ALTER TABLE sets ADD COLUMN IF NOT EXISTS condition_expression TEXT;                                -- The membership condition (the predicate / definition) phi defining the set.
ALTER TABLE sets ADD COLUMN IF NOT EXISTS is_self_referential BOOLEAN;                              -- Whether the condition refers to the set's own membership.
ALTER TABLE sets ADD COLUMN IF NOT EXISTS memberships TEXT;                                         -- Membership facts for which this set is the container.
COMMENT ON TABLE sets IS 'The universe of sets under discussion. Each set is identified by a slug and defined by a membership condition.';
COMMENT ON COLUMN sets.set_id IS 'Stored identity slug, e.g. ''russell-set''.';
COMMENT ON COLUMN sets.label IS 'Human notation for the set, e.g. ''{a}'', ''R'', ''∅''.';
COMMENT ON COLUMN sets.condition_expression IS 'The membership condition (the predicate / definition) phi defining the set.';
COMMENT ON COLUMN sets.is_self_referential IS 'Whether the condition refers to the set''s own membership.';
COMMENT ON COLUMN sets.memberships IS 'Membership facts for which this set is the container.';

-- ----------------------------------------------------------------------------
-- MembershipFacts: The core relation: each fact is a question 'Element in Container' carrying its three-valued answer.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS membership_facts (
  membership_fact_id                  TEXT                 PRIMARY KEY          -- Stored identity, e.g. 'russell-set-in-russell-set'.
);
ALTER TABLE membership_facts ADD COLUMN IF NOT EXISTS element TEXT;                                 -- The candidate member (itself a set).
ALTER TABLE membership_facts ADD COLUMN IF NOT EXISTS container TEXT;                               -- The set being asked about.
ALTER TABLE membership_facts ADD COLUMN IF NOT EXISTS membership_value TEXT;                        -- The three-valued answer to Element in Container.
ALTER TABLE membership_facts ADD COLUMN IF NOT EXISTS evaluation_steps TEXT;                        -- The fixed-point evaluation trials for this fact.
COMMENT ON TABLE membership_facts IS 'The core relation: each fact is a question ''Element in Container'' carrying its three-valued answer.';
COMMENT ON COLUMN membership_facts.membership_fact_id IS 'Stored identity, e.g. ''russell-set-in-russell-set''.';
COMMENT ON COLUMN membership_facts.element IS 'The candidate member (itself a set).';
COMMENT ON COLUMN membership_facts.container IS 'The set being asked about.';
COMMENT ON COLUMN membership_facts.membership_value IS 'The three-valued answer to Element in Container.';
COMMENT ON COLUMN membership_facts.evaluation_steps IS 'The fixed-point evaluation trials for this fact.';

-- ----------------------------------------------------------------------------
-- EvaluationSteps: Strong Kleene fixed-point evaluation of the Russell fact: each trial value fed through phi = not(R in R). Only NULL is stable, dissolving the Russell paradox into a single ungrounded fixed point.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS evaluation_steps (
  evaluation_step_id                  TEXT                 PRIMARY KEY          -- Stored identity of the trial.
);
ALTER TABLE evaluation_steps ADD COLUMN IF NOT EXISTS membership_fact TEXT;                         -- The fact being evaluated.
ALTER TABLE evaluation_steps ADD COLUMN IF NOT EXISTS step_order INTEGER;                           -- Trial order (1,2,3).
ALTER TABLE evaluation_steps ADD COLUMN IF NOT EXISTS trial_value TEXT;                             -- The truth value assumed for R in R before applying phi.
ALTER TABLE evaluation_steps ADD COLUMN IF NOT EXISTS resulting_value TEXT;                         -- The value phi = not(R in R) yields under that assumption.
COMMENT ON TABLE evaluation_steps IS 'Strong Kleene fixed-point evaluation of the Russell fact: each trial value fed through phi = not(R in R). Only NULL is stable, dissolving the Russell paradox into a single ungrounded fixed point.';
COMMENT ON COLUMN evaluation_steps.evaluation_step_id IS 'Stored identity of the trial.';
COMMENT ON COLUMN evaluation_steps.membership_fact IS 'The fact being evaluated.';
COMMENT ON COLUMN evaluation_steps.step_order IS 'Trial order (1,2,3).';
COMMENT ON COLUMN evaluation_steps.trial_value IS 'The truth value assumed for R in R before applying phi.';
COMMENT ON COLUMN evaluation_steps.resulting_value IS 'The value phi = not(R in R) yields under that assumption.';

